package com.yuegang.zhihui.inventory.application;
import com.yuegang.zhihui.common.core.*;import com.yuegang.zhihui.inventory.api.*;import java.util.*;import javax.sql.*;import org.springframework.jdbc.core.*;import org.springframework.jdbc.datasource.*;import org.springframework.transaction.support.*;
public final class InventoryService{private final JdbcTemplate jdbc;private final TransactionTemplate tx;public InventoryService(DataSource d){jdbc=new JdbcTemplate(d);tx=new TransactionTemplate(new DataSourceTransactionManager(d));}public InventoryView get(String sku){long id=id(sku);return jdbc.query("SELECT available_quantity,locked_quantity,sold_quantity,version FROM inventory_stock WHERE sku_id=?",r->{if(!r.next())throw new BusinessException(ErrorCode.RESOURCE_NOT_FOUND);return new InventoryView(sku,r.getLong(1),r.getLong(2),r.getLong(3),r.getLong(4));},id);}public InventoryView adjust(InventoryCommand c){return tx.execute(s->{long sku=id(c.skuId());jdbc.update("INSERT INTO inventory_stock(sku_id,available_quantity) VALUES(?,0) ON DUPLICATE KEY UPDATE sku_id=VALUES(sku_id)",sku);int duplicate=jdbc.queryForObject("SELECT COUNT(*) FROM inventory_ledger WHERE request_id=? AND movement_type='ADJUST'",Integer.class,c.requestId());if(duplicate==0){jdbc.update("UPDATE inventory_stock SET available_quantity=available_quantity+?,version=version+1 WHERE sku_id=?",c.quantity(),sku);ledger(sku,"ADJUST",c.quantity(),0,0,c);}return get(c.skuId());});}public InventoryView reserve(InventoryCommand c){return tx.execute(s->{long sku=id(c.skuId());Integer exists=jdbc.queryForObject("SELECT COUNT(*) FROM inventory_reservation WHERE request_id=?",Integer.class,c.requestId());if(exists>0)return get(c.skuId());int changed=jdbc.update("UPDATE inventory_stock SET available_quantity=available_quantity-?,locked_quantity=locked_quantity+?,version=version+1 WHERE sku_id=? AND available_quantity>=?",c.quantity(),c.quantity(),sku,c.quantity());if(changed!=1)throw new BusinessException(ErrorCode.BUSINESS_CONFLICT);jdbc.update("INSERT INTO inventory_reservation(id,request_id,sku_id,quantity,reference_type,reference_id,status,expires_at) VALUES(?,?,?,?,?,?,'LOCKED',DATE_ADD(NOW(6),INTERVAL 30 MINUTE))",next(),c.requestId(),sku,c.quantity(),c.referenceType(),c.referenceId());ledger(sku,"RESERVE",-c.quantity(),c.quantity(),0,c);return get(c.skuId());});}public InventoryView confirm(InventoryCommand c){return transition(c,"LOCKED","SOLD",0,-c.quantity(),c.quantity(),"CONFIRM");}public InventoryView release(InventoryCommand c){return transition(c,"LOCKED","RELEASED",c.quantity(),-c.quantity(),0,"RELEASE");}private InventoryView transition(InventoryCommand c,String from,String to,long available,long locked,long sold,String type){return tx.execute(s->{long sku=id(c.skuId());int row=jdbc.update("UPDATE inventory_reservation SET status=?,version=version+1 WHERE request_id=? AND sku_id=? AND status=? AND quantity=?",to,c.requestId(),sku,from,c.quantity());if(row==0){Integer done=jdbc.queryForObject("SELECT COUNT(*) FROM inventory_reservation WHERE request_id=? AND status=?",Integer.class,c.requestId(),to);if(done>0)return get(c.skuId());throw new BusinessException(ErrorCode.BUSINESS_CONFLICT);}int stock=jdbc.update("UPDATE inventory_stock SET available_quantity=available_quantity+?,locked_quantity=locked_quantity+?,sold_quantity=sold_quantity+?,version=version+1 WHERE sku_id=? AND locked_quantity>=?",available,locked,sold,sku,c.quantity());if(stock!=1)throw new BusinessException(ErrorCode.BUSINESS_CONFLICT);ledger(sku,type,available,locked,sold,c);return get(c.skuId());});}private void ledger(long sku,String type,long a,long l,long sold,InventoryCommand c){jdbc.update("INSERT INTO inventory_ledger(id,sku_id,movement_type,available_delta,locked_delta,sold_delta,reference_type,reference_id,request_id) VALUES(?,?,?,?,?,?,?,?,?)",next(),sku,type,a,l,sold,c.referenceType(),c.referenceId(),c.requestId());}private static long next(){return UUID.randomUUID().getMostSignificantBits()&Long.MAX_VALUE;}private static long id(String s){try{long v=Long.parseLong(s);if(v<=0)throw new NumberFormatException();return v;}catch(NumberFormatException e){throw new BusinessException(ErrorCode.VALIDATION_ERROR);}}}
